323	  /**
324	   * For the given Enum value {@code rank}, returns the value's {@code "EnumClass.name"}, which is
325	   * used in exception and warning output.
326	   */
327	  private static String getLockName(Enum<?> rank) {
328	    return rank.getDeclaringClass().getSimpleName() + "." + rank.name();
329	  }
