331	  /**
332	   * A {@code CycleDetectingLockFactory.WithExplicitOrdering} provides the additional enforcement of
333	   * an application-specified ordering of lock acquisitions. The application defines the allowed
334	   * ordering with an {@code Enum} whose values each correspond to a lock type. The order in which
335	   * the values are declared dictates the allowed order of lock acquisition. In other words, locks
336	   * corresponding to smaller values of {@link Enum#ordinal()} should only be acquired before locks
337	   * with larger ordinals. Example:
338	   *
339	   * {@snippet :
340	   * enum MyLockOrder {
341	   *   FIRST, SECOND, THIRD;
342	   * }
343	   *
344	   * CycleDetectingLockFactory.WithExplicitOrdering<MyLockOrder> factory =
345	   *     CycleDetectingLockFactory.newInstanceWithExplicitOrdering(Policies.THROW);
346	   *
347	   * Lock lock1 = factory.newReentrantLock(MyLockOrder.FIRST);
348	   * Lock lock2 = factory.newReentrantLock(MyLockOrder.SECOND);
349	   * Lock lock3 = factory.newReentrantLock(MyLockOrder.THIRD);
350	   *
351	   * lock1.lock();
352	   * lock3.lock();
353	   * lock2.lock(); // will throw an IllegalStateException
354	   * }
355	   *
356	   * <p>As with all locks created by instances of {@code CycleDetectingLockFactory} explicitly
357	   * ordered locks participate in general cycle detection with all other cycle detecting locks, and
358	   * a lock's behavior when detecting a cyclic lock acquisition is defined by the {@code Policy} of
359	   * the factory that created it.
360	   *
361	   * <p>Note, however, that although multiple locks can be created for a given Enum value, whether
362	   * it be through separate factory instances or through multiple calls to the same factory,
363	   * attempting to acquire multiple locks with the same Enum value (within the same thread) will
364	   * result in an IllegalStateException regardless of the factory's policy. For example:
365	   *
366	   * {@snippet :
367	   * CycleDetectingLockFactory.WithExplicitOrdering<MyLockOrder> factory1 =
368	   *     CycleDetectingLockFactory.newInstanceWithExplicitOrdering(...);
369	   * CycleDetectingLockFactory.WithExplicitOrdering<MyLockOrder> factory2 =
370	   *     CycleDetectingLockFactory.newInstanceWithExplicitOrdering(...);
371	   *
372	   * Lock lockA = factory1.newReentrantLock(MyLockOrder.FIRST);
373	   * Lock lockB = factory1.newReentrantLock(MyLockOrder.FIRST);
374	   * Lock lockC = factory2.newReentrantLock(MyLockOrder.FIRST);
375	   *
376	   * lockA.lock();
377	   *
378	   * lockB.lock(); // will throw an IllegalStateException
379	   * lockC.lock(); // will throw an IllegalStateException
380	   *
381	   * lockA.lock(); // reentrant acquisition is okay
382	   * }
383	   *
384	   * <p>It is the responsibility of the application to ensure that multiple lock instances with the
385	   * same rank are never acquired in the same thread.
386	   *
387	   * @param <E> The Enum type representing the explicit lock ordering.
388	   * @since 13.0
389	   */
390	  public static final class WithExplicitOrdering<E extends Enum<E>>
391	      extends CycleDetectingLockFactory {
392	
393	    private final Map<E, LockGraphNode> lockGraphNodes;
394	
395	    @VisibleForTesting
396	    WithExplicitOrdering(Policy policy, Map<E, LockGraphNode> lockGraphNodes) {
397	      super(policy);
398	      this.lockGraphNodes = lockGraphNodes;
399	    }
400	
401	    /** Equivalent to {@code newReentrantLock(rank, false)}. */
402	    public ReentrantLock newReentrantLock(E rank) {
403	      return newReentrantLock(rank, false);
404	    }
405	
406	    /**
407	     * Creates a {@link ReentrantLock} with the given fairness policy and rank. The values returned
408	     * by {@link Enum#getDeclaringClass()} and {@link Enum#name()} are used to describe the lock in
409	     * warning or exception output.
410	     *
411	     * @throws IllegalStateException If the factory has already created a {@code Lock} with the
412	     *     specified rank.
413	     */
414	    public ReentrantLock newReentrantLock(E rank, boolean fair) {
415	      return policy == Policies.DISABLED
416	          ? new ReentrantLock(fair)
417	          // requireNonNull is safe because createNodes inserts an entry for every E.
418	          // (If the caller passes `null` for the `rank` parameter, this will throw, but that's OK.)
419	          : new CycleDetectingReentrantLock(requireNonNull(lockGraphNodes.get(rank)), fair);
420	    }
421	
422	    /** Equivalent to {@code newReentrantReadWriteLock(rank, false)}. */
423	    public ReentrantReadWriteLock newReentrantReadWriteLock(E rank) {
424	      return newReentrantReadWriteLock(rank, false);
425	    }
426	
427	    /**
428	     * Creates a {@link ReentrantReadWriteLock} with the given fairness policy and rank. The values
429	     * returned by {@link Enum#getDeclaringClass()} and {@link Enum#name()} are used to describe the
430	     * lock in warning or exception output.
431	     *
432	     * @throws IllegalStateException If the factory has already created a {@code Lock} with the
433	     *     specified rank.
434	     */
435	    public ReentrantReadWriteLock newReentrantReadWriteLock(E rank, boolean fair) {
436	      return policy == Policies.DISABLED
437	          ? new ReentrantReadWriteLock(fair)
438	          // requireNonNull is safe because createNodes inserts an entry for every E.
439	          // (If the caller passes `null` for the `rank` parameter, this will throw, but that's OK.)
440	          : new CycleDetectingReentrantReadWriteLock(
441	              requireNonNull(lockGraphNodes.get(rank)), fair);
442	    }
443	  }
