447	  private static final LazyLogger logger = new LazyLogger(CycleDetectingLockFactory.class);
448	
449	  final Policy policy;
450	
451	  private CycleDetectingLockFactory(Policy policy) {
452	    this.policy = checkNotNull(policy);
453	  }
