455	  /**
456	   * Tracks the currently acquired locks for each Thread, kept up to date by calls to {@link
457	   * #aboutToAcquire(CycleDetectingLock)} and {@link #lockStateChanged(CycleDetectingLock)}.
458	   */
459	  // This is logically a Set, but an ArrayList is used to minimize the amount
460	  // of allocation done on lock()/unlock().
461	  private static final ThreadLocal<List<LockGraphNode>> acquiredLocks =
462	      new ThreadLocal<List<LockGraphNode>>() {
463	        @Override
464	        protected List<LockGraphNode> initialValue() {
465	          return newArrayListWithCapacity(3);
466	        }
467	      };
468	
469	  /**
470	   * A Throwable used to record a stack trace that illustrates an example of a specific lock
471	   * acquisition ordering. The top of the stack trace is truncated such that it starts with the
472	   * acquisition of the lock in question, e.g.
473	   *
474	   * <pre>
475	   * com...ExampleStackTrace: LockB -&gt; LockC
476	   *   at com...CycleDetectingReentrantLock.lock(CycleDetectingLockFactory.java:443)
477	   *   at ...
478	   *   at ...
479	   *   at com...MyClass.someMethodThatAcquiresLockB(MyClass.java:123)
480	   * </pre>
481	   */
482	  private static class ExampleStackTrace extends IllegalStateException {
483	
484	    static final StackTraceElement[] EMPTY_STACK_TRACE = new StackTraceElement[0];
485	
486	    static final ImmutableSet<String> EXCLUDED_CLASS_NAMES =
487	        ImmutableSet.of(
488	            CycleDetectingLockFactory.class.getName(),
489	            ExampleStackTrace.class.getName(),
490	            LockGraphNode.class.getName());
491	
492	    ExampleStackTrace(LockGraphNode node1, LockGraphNode node2) {
493	      super(node1.getLockName() + " -> " + node2.getLockName());
494	      StackTraceElement[] origStackTrace = getStackTrace();
495	      for (int i = 0, n = origStackTrace.length; i < n; i++) {
496	        if (WithExplicitOrdering.class.getName().equals(origStackTrace[i].getClassName())) {
497	          // For pre-populated disallowedPriorLocks edges, omit the stack trace.
498	          setStackTrace(EMPTY_STACK_TRACE);
499	          break;
500	        }
501	        if (!EXCLUDED_CLASS_NAMES.contains(origStackTrace[i].getClassName())) {
502	          setStackTrace(Arrays.copyOfRange(origStackTrace, i, n));
503	          break;
504	        }
505	      }
506	    }
507	  }
