509	  /**
510	   * Represents a detected cycle in lock acquisition ordering. The exception includes a causal chain
511	   * of {@code ExampleStackTrace} instances to illustrate the cycle, e.g.
512	   *
513	   * <pre>
514	   * com....PotentialDeadlockException: Potential Deadlock from LockC -&gt; ReadWriteA
515	   *   at ...
516	   *   at ...
517	   * Caused by: com...ExampleStackTrace: LockB -&gt; LockC
518	   *   at ...
519	   *   at ...
520	   * Caused by: com...ExampleStackTrace: ReadWriteA -&gt; LockB
521	   *   at ...
522	   *   at ...
523	   * </pre>
524	   *
525	   * <p>Instances are logged for the {@code Policies.WARN}, and thrown for {@code Policies.THROW}.
526	   *
527	   * @since 13.0
528	   */
529	  public static final class PotentialDeadlockException extends ExampleStackTrace {
530	
531	    private final ExampleStackTrace conflictingStackTrace;
532	
533	    private PotentialDeadlockException(
534	        LockGraphNode node1, LockGraphNode node2, ExampleStackTrace conflictingStackTrace) {
535	      super(node1, node2);
536	      this.conflictingStackTrace = conflictingStackTrace;
537	      initCause(conflictingStackTrace);
538	    }
539	
540	    public ExampleStackTrace getConflictingStackTrace() {
541	      return conflictingStackTrace;
542	    }
543	
544	    /**
545	     * Appends the chain of messages from the {@code conflictingStackTrace} to the original {@code
546	     * message}.
547	     */
548	    @Override
549	    public String getMessage() {
550	      // requireNonNull is safe because ExampleStackTrace sets a non-null message.
551	      StringBuilder message = new StringBuilder(requireNonNull(super.getMessage()));
552	      for (Throwable t = conflictingStackTrace; t != null; t = t.getCause()) {
553	        message.append(", ").append(t.getMessage());
554	      }
555	      return message.toString();
556	    }
557	  }
