559	  /**
560	   * Internal Lock implementations implement the {@code CycleDetectingLock} interface, allowing the
561	   * detection logic to treat all locks in the same manner.
562	   */
563	  private interface CycleDetectingLock {
564	
565	    /**
566	     * @return the {@link LockGraphNode} associated with this lock.
567	     */
568	    LockGraphNode getLockGraphNode();
569	
570	    /**
571	     * @return {@code true} if the current thread has acquired this lock.
572	     */
573	    boolean isAcquiredByCurrentThread();
574	  }
575	
576	  /**
577	   * A {@code LockGraphNode} associated with each lock instance keeps track of the directed edges in
578	   * the lock acquisition graph.
579	   */
580	  private static final class LockGraphNode {
581	
582	    /**
583	     * The map tracking the locks that are known to be acquired before this lock, each associated
584	     * with an example stack trace. Locks are weakly keyed to allow proper garbage collection when
585	     * they are no longer referenced.
586	     */
587	    final Map<LockGraphNode, ExampleStackTrace> allowedPriorLocks =
588	        new MapMaker().weakKeys().makeMap();
589	
590	    /**
591	     * The map tracking lock nodes that can cause a lock acquisition cycle if acquired before this
592	     * node.
593	     */
594	    final Map<LockGraphNode, PotentialDeadlockException> disallowedPriorLocks =
595	        new MapMaker().weakKeys().makeMap();
596	
597	    final String lockName;
598	
599	    LockGraphNode(String lockName) {
600	      this.lockName = Preconditions.checkNotNull(lockName);
601	    }
602	
603	    String getLockName() {
604	      return lockName;
605	    }
606	
607	    void checkAcquiredLocks(Policy policy, List<LockGraphNode> acquiredLocks) {
608	      for (LockGraphNode acquiredLock : acquiredLocks) {
609	        checkAcquiredLock(policy, acquiredLock);
610	      }
611	    }
612	
613	    /**
614	     * Checks the acquisition-ordering between {@code this}, which is about to be acquired, and the
615	     * specified {@code acquiredLock}.
616	     *
617	     * <p>When this method returns, the {@code acquiredLock} should be in either the {@code
618	     * preAcquireLocks} map, for the case in which it is safe to acquire {@code this} after the
619	     * {@code acquiredLock}, or in the {@code disallowedPriorLocks} map, in which case it is not
620	     * safe.
621	     */
622	    void checkAcquiredLock(Policy policy, LockGraphNode acquiredLock) {
623	      // checkAcquiredLock() should never be invoked by a lock that has already
624	      // been acquired. For unordered locks, aboutToAcquire() ensures this by
625	      // checking isAcquiredByCurrentThread(). For ordered locks, however, this
626	      // can happen because multiple locks may share the same LockGraphNode. In
627	      // this situation, throw an IllegalStateException as defined by contract
628	      // described in the documentation of WithExplicitOrdering.
629	      Preconditions.checkState(
630	          this != acquiredLock,
631	          "Attempted to acquire multiple locks with the same rank %s",
632	          acquiredLock.getLockName());
633	
634	      if (allowedPriorLocks.containsKey(acquiredLock)) {
635	        // The acquisition ordering from "acquiredLock" to "this" has already
636	        // been verified as safe. In a properly written application, this is
637	        // the common case.
638	        return;
639	      }
640	      PotentialDeadlockException previousDeadlockException = disallowedPriorLocks.get(acquiredLock);
641	      if (previousDeadlockException != null) {
642	        // Previously determined to be an unsafe lock acquisition.
643	        // Create a new PotentialDeadlockException with the same causal chain
644	        // (the example cycle) as that of the cached exception.
645	        PotentialDeadlockException exception =
646	            new PotentialDeadlockException(
647	                acquiredLock, this, previousDeadlockException.getConflictingStackTrace());
648	        policy.handlePotentialDeadlock(exception);
649	        return;
650	      }
651	      // Otherwise, it's the first time seeing this lock relationship. Look for
652	      // a path from the acquiredLock to this.
653	      Set<LockGraphNode> seen = newIdentityHashSet();
654	      ExampleStackTrace path = acquiredLock.findPathTo(this, seen);
655	
656	      if (path == null) {
657	        // this can be safely acquired after the acquiredLock.
658	        //
659	        // Note that there is a race condition here which can result in missing
660	        // a cyclic edge: it's possible for two threads to simultaneous find
661	        // "safe" edges which together form a cycle. Preventing this race
662	        // condition efficiently without _introducing_ deadlock is probably
663	        // tricky. For now, just accept the race condition---missing a warning
664	        // now and then is still better than having no deadlock detection.
665	        allowedPriorLocks.put(acquiredLock, new ExampleStackTrace(acquiredLock, this));
666	      } else {
667	        // Unsafe acquisition order detected. Create and cache a
668	        // PotentialDeadlockException.
669	        PotentialDeadlockException exception =
670	            new PotentialDeadlockException(acquiredLock, this, path);
671	        disallowedPriorLocks.put(acquiredLock, exception);
672	        policy.handlePotentialDeadlock(exception);
673	      }
674	    }
675	
676	    /**
677	     * Performs a depth-first traversal of the graph edges defined by each node's {@code
678	     * allowedPriorLocks} to find a path between {@code this} and the specified {@code lock}.
679	     *
680	     * @return If a path was found, a chained {@link ExampleStackTrace} illustrating the path to the
681	     *     {@code lock}, or {@code null} if no path was found.
682	     */
683	    private @Nullable ExampleStackTrace findPathTo(LockGraphNode node, Set<LockGraphNode> seen) {
684	      if (!seen.add(this)) {
685	        return null; // Already traversed this node.
686	      }
687	      ExampleStackTrace found = allowedPriorLocks.get(node);
688	      if (found != null) {
689	        return found; // Found a path ending at the node!
690	      }
691	      // Recurse the edges.
692	      for (Entry<LockGraphNode, ExampleStackTrace> entry : allowedPriorLocks.entrySet()) {
693	        LockGraphNode preAcquiredLock = entry.getKey();
694	        found = preAcquiredLock.findPathTo(node, seen);
695	        if (found != null) {
696	          // One of this node's allowedPriorLocks found a path. Prepend an
697	          // ExampleStackTrace(preAcquiredLock, this) to the returned chain of
698	          // ExampleStackTraces.
699	          ExampleStackTrace path = new ExampleStackTrace(preAcquiredLock, this);
700	          path.setStackTrace(entry.getValue().getStackTrace());
701	          path.initCause(found);
702	          return path;
703	        }
704	      }
705	      return null;
706	    }
707	  }
708	
709	  /**
710	   * CycleDetectingLock implementations must call this method before attempting to acquire the lock.
711	   */
712	  private void aboutToAcquire(CycleDetectingLock lock) {
713	    if (!lock.isAcquiredByCurrentThread()) {
714	      // requireNonNull accommodates Android's @RecentlyNullable annotation on ThreadLocal.get
715	      List<LockGraphNode> acquiredLockList = requireNonNull(acquiredLocks.get());
716	      LockGraphNode node = lock.getLockGraphNode();
717	      node.checkAcquiredLocks(policy, acquiredLockList);
718	      acquiredLockList.add(node);
719	    }
720	  }
721	
722	  /**
723	   * CycleDetectingLock implementations must call this method in a {@code finally} clause after any
724	   * attempt to change the lock state, including both lock and unlock attempts. Failure to do so can
725	   * result in corrupting the acquireLocks set.
726	   */
727	  private static void lockStateChanged(CycleDetectingLock lock) {
728	    if (!lock.isAcquiredByCurrentThread()) {
729	      // requireNonNull accommodates Android's @RecentlyNullable annotation on ThreadLocal.get
730	      List<LockGraphNode> acquiredLockList = requireNonNull(acquiredLocks.get());
731	      LockGraphNode node = lock.getLockGraphNode();
732	      // Iterate in reverse because locks are usually locked/unlocked in a
733	      // LIFO order.
734	      for (int i = acquiredLockList.size() - 1; i >= 0; i--) {
735	        if (acquiredLockList.get(i) == node) {
736	          acquiredLockList.remove(i);
737	          break;
738	        }
739	      }
