618	     * preAcquireLocks} map, for the case in which it is safe to acquire {@code this} after the
619	     * {@code acquiredLock}, or in the {@code disallowedPriorLocks} map, in which case it is not
620	     * safe.
621	     */
622	    void checkAcquiredLock(Policy policy, LockGraphNode acquiredLock) {
623	      // checkAcquiredLock() should never be invoked by a lock that has already
624	      // been acquired. For unordered locks, aboutToAcquire() ensures this by
625	      // checking isAcquiredByCurrentThread(). For ordered locks, however, this
626	      // can happen because multiple locks may share the same LockGraphNode. In
627	      // this situation, throw an IllegalStateException as defined by contract
628	      // described in the documentation of WithExplicitOrdering.
629	      Preconditions.checkState(
630	          this != acquiredLock,
631	          "Attempted to acquire multiple locks with the same rank %s",
632	          acquiredLock.getLockName());
633	
634	      if (allowedPriorLocks.containsKey(acquiredLock)) {
635	        // The acquisition ordering from "acquiredLock" to "this" has already
636	        // been verified as safe. In a properly written application, this is
637	        // the common case.
638	        return;
639	      }
640	      PotentialDeadlockException previousDeadlockException = disallowedPriorLocks.get(acquiredLock);
641	      if (previousDeadlockException != null) {
642	        // Previously determined to be an unsafe lock acquisition.
643	        // Create a new PotentialDeadlockException with the same causal chain
644	        // (the example cycle) as that of the cached exception.
645	        PotentialDeadlockException exception =
646	            new PotentialDeadlockException(
647	                acquiredLock, this, previousDeadlockException.getConflictingStackTrace());
648	        policy.handlePotentialDeadlock(exception);
649	        return;
650	      }
651	      // Otherwise, it's the first time seeing this lock relationship. Look for
652	      // a path from the acquiredLock to this.
653	      Set<LockGraphNode> seen = newIdentityHashSet();
654	      ExampleStackTrace path = acquiredLock.findPathTo(this, seen);
655	
656	      if (path == null) {
657	        // this can be safely acquired after the acquiredLock.
658	        //
659	        // Note that there is a race condition here which can result in missing
660	        // a cyclic edge: it's possible for two threads to simultaneous find
661	        // "safe" edges which together form a cycle. Preventing this race
662	        // condition efficiently without _introducing_ deadlock is probably
663	        // tricky. For now, just accept the race condition---missing a warning
664	        // now and then is still better than having no deadlock detection.
665	        allowedPriorLocks.put(acquiredLock, new ExampleStackTrace(acquiredLock, this));
666	      } else {
667	        // Unsafe acquisition order detected. Create and cache a
668	        // PotentialDeadlockException.
669	        PotentialDeadlockException exception =
670	            new PotentialDeadlockException(acquiredLock, this, path);
671	        disallowedPriorLocks.put(acquiredLock, exception);
672	        policy.handlePotentialDeadlock(exception);
673	      }
674	    }
