83	  /*
84	   * c.g.c.collect.testing.Helpers.misleadingSizeList has a broken Iterator, so we can't use it. (I
85	   * mean, ideally we'd fix it....) Also, we specifically need a List so that we trigger the fast
86	   * path in join(Iterable).
87	   */
88	  private static final class MisleadingSizeList<E extends @Nullable Object>
89	      extends ForwardingList<E> {
90	    final List<E> delegate;
91	    final int delta;
92	
93	    MisleadingSizeList(List<E> delegate, int delta) {
94	      this.delegate = delegate;
95	      this.delta = delta;
96	    }
97	
98	    @Override
99	    protected List<E> delegate() {
100	      return delegate;
101	    }
102	
103	    @Override
104	    public int size() {
105	      return delegate.size() + delta;
106	    }
107	  }
