225	  private static void checkResult(
226	      Joiner joiner, Iterable<? extends @Nullable Integer> parts, String expected) {
227	    assertThat(joiner.join(parts)).isEqualTo(expected);
228	    assertThat(joiner.join(parts.iterator())).isEqualTo(expected);
229	
230	    StringBuilder sb1FromIterable = new StringBuilder().append('x');
231	    joiner.appendTo(sb1FromIterable, parts);
232	    assertThat(sb1FromIterable.toString()).isEqualTo("x" + expected);
233	
234	    StringBuilder sb1FromIterator = new StringBuilder().append('x');
235	    joiner.appendTo(sb1FromIterator, parts.iterator());
236	    assertThat(sb1FromIterator.toString()).isEqualTo("x" + expected);
237	
238	    // The use of iterator() works around J2KT b/381065164.
239	    @Nullable Integer[] partsArray =
240	        newArrayList(parts.iterator()).toArray(new @Nullable Integer[0]);
241	    assertThat(joiner.join(partsArray)).isEqualTo(expected);
242	
243	    StringBuilder sb2 = new StringBuilder().append('x');
244	    joiner.appendTo(sb2, partsArray);
245	    assertThat(sb2.toString()).isEqualTo("x" + expected);
246	
247	    int num = partsArray.length - 2;
248	    if (num >= 0) {
249	      @Nullable Object[] rest = new @Nullable Object[num];
250	      for (int i = 0; i < num; i++) {
251	        rest[i] = partsArray[i + 2];
252	      }
253	
254	      assertThat(joiner.join(partsArray[0], partsArray[1], rest)).isEqualTo(expected);
255	
256	      StringBuilder sb3 = new StringBuilder().append('x');
257	      joiner.appendTo(sb3, partsArray[0], partsArray[1], rest);
258	      assertThat(sb3.toString()).isEqualTo("x" + expected);
259	    }
260	  }
